<?php $title='Dashboard';require __DIR__.'/_layout.php';$q=['Posts'=>"SELECT COUNT(*) FROM posts",'Published'=>"SELECT COUNT(*) FROM posts WHERE status='published'",'Drafts'=>"SELECT COUNT(*) FROM posts WHERE status='draft'",'Users'=>"SELECT COUNT(*) FROM users",'Comments'=>"SELECT COUNT(*) FROM comments",'Pending comments'=>"SELECT COUNT(*) FROM comments WHERE status='pending'",'Views'=>"SELECT COALESCE(SUM(view_count),0) FROM posts",'Subscribers'=>"SELECT COUNT(*) FROM subscribers WHERE status='active'",'Messages'=>"SELECT COUNT(*) FROM contact_messages"];?><h1>Dashboard</h1><div class="stats"><?php foreach($q as $n=>$sql): ?><div class="stat"><div class="muted"><?=e($n)?></div><h2><?=number_format((int)db()->query($sql)->fetchColumn())?></h2></div><?php endforeach;?></div><section class="section"><h2>Recent activity</h2><table class="table"><tr><th>Action</th><th>User</th><th>Date</th></tr><?php foreach(db()->query("SELECT a.*,u.name FROM activity_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 15") as $a):?><tr><td><?=e($a['action'])?> <?=e($a['entity'])?></td><td><?=e($a['name']??'System')?></td><td><?=e($a['created_at'])?></td></tr><?php endforeach;?></table></section><?php require __DIR__.'/_footer.php';?>